610	/**
611	 * Extracts the hook name from an extension path.
612	 * Format: file://path/to/file.js:hookName or file://path/to/file.py:hook_name
613	 * @returns The hook name or undefined if not specified
614	 */
615	export function getExtensionHookName(extension: string): string | undefined {
616	  if (!extension.startsWith('file://')) {
617	    return undefined;
618	  }
619	  const lastColonIndex = extension.lastIndexOf(':');
620	  // Check if colon is part of Windows drive letter (position 8 after file://) or not present
621	  if (lastColonIndex > 8) {
622	    const functionName = extension.slice(lastColonIndex + 1);
623	    // Return undefined for empty strings (e.g., "file://hooks.js:")
624	    return functionName || undefined;
625	  }
626	  return undefined;
627	}
